import{_ as t,o as e,c as s,a2 as r}from"./chunks/framework.BXzK3EA4.js";const a="/assets/image-key2025030604.CRZe4xdw.png",n="/assets/image-key2025030605.M1WpYft-.png",i="/assets/image-key2025030606.CVwUfdHK.png",l="/assets/image-key2025030607.mQ321IKw.png",p="/assets/image-key2025030608.wr7dOtWX.png",d="/assets/image-key2025030609zh.VPeEGyih.png",g="/assets/image-key2025030610.zBAXA-oL.png",c="/assets/image-key2025030611.5KXV_KbB.png",h="/assets/image-key2025030612.BVcf3FKa.png",_="/assets/image-key2025030613.CRj7VfPW.png",m="/assets/image-key2025030614zh.C5ntm1Ct.png",u="/assets/image-key2025030615zh.DFXn4OBA.png",x=JSON.parse('{"title":"如何使用私钥进行远程登录","description":"","frontmatter":{"title":"如何使用私钥进行远程登录"},"headers":[],"relativePath":"ops-knowledge-base/vps/remote-login-with-private-key.md","filePath":"ops-knowledge-base/vps/remote-login-with-private-key.md","lastUpdated":1788259091000}'),P={name:"ops-knowledge-base/vps/remote-login-with-private-key.md"};function k(S,o,f,b,y,q){return e(),s("div",null,[...o[0]||(o[0]=[r('<p><strong>本文介绍如何使用不同的系统和远程工具通过私钥进行远程登录</strong></p><h2 id="配置-ssh-服务允许使用密钥登录" tabindex="-1">配置 SSH 服务允许使用密钥登录 <a class="header-anchor" href="#配置-ssh-服务允许使用密钥登录" aria-label="Permalink to &quot;配置 SSH 服务允许使用密钥登录&quot;">​</a></h2><p>在 <strong>远程服务器</strong> 上，确保 SSH 配置允许密钥认证：</p><ol><li>编辑 <code>/etc/ssh/sshd_config</code> 文件：</li></ol><p>#sudo vi /etc/ssh/sshd_config</p><pre><code>2. 确保以下行存在，并且没有被注释（没有 `#`）：\n</code></pre><p>PubkeyAuthentication yes</p><p>AuthorizedKeysFile .ssh/authorized_keys</p><p>PasswordAuthentication no # 如果你希望禁用密码登录</p><h2 id="一、mac终端登录方式" tabindex="-1">一、mac终端登录方式 <a class="header-anchor" href="#一、mac终端登录方式" aria-label="Permalink to &quot;一、mac终端登录方式&quot;">​</a></h2><h2 id="_1-从远程服务器下载私钥" tabindex="-1">1. 从远程服务器下载私钥 <a class="header-anchor" href="#_1-从远程服务器下载私钥" aria-label="Permalink to &quot;1. 从远程服务器下载私钥&quot;">​</a></h2><p>1.1 使用 SCP 命令下载私钥</p><p>假设远程服务器的 <strong>IP 地址</strong> 是 <code>192.168.1.100</code>，用户名是 <code>root</code>，且私钥文件位于远程服务器上的 <code>/root/.ssh/id_ed25519</code>。你可以使用 <strong>SCP（Secure Copy Protocol）</strong> 从远程服务器下载私钥到 <strong>Mac</strong> 上。</p><p>在 <strong>Mac 终端</strong> 上执行以下命令：</p><p>#scp <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a>:/root/.ssh/id_ed25519 ~/.ssh/id_ed25519</p><ul><li><strong><code>root@192.168.1.100</code>：远程服务器的用户名和 IP 地址。</strong></li><li><strong>/root/.ssh/id_ed25519：远程服务器上私钥的路径。</strong></li><li><strong><code>~/.ssh/id_ed25519</code>：本地 Mac 计算机上存储私钥的路径。</strong></li></ul><p><strong>如果你想指定远程服务的端口，使用 <code>-P</code>（大写 <code>P</code>）加端口号。</strong></p><p>#scp -P 56251 <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a>:/root/.ssh/id_ed25519 ~/.ssh/id_ed25519</p><p>1.2 输入密码</p><p>在执行上述命令时，系统会要求你输入 <strong>远程服务器的密码</strong>。输入密码后，私钥会被安全地复制到本地 <code>~/.ssh/</code> 目录下。</p><p><strong>示例：</strong></p><p><strong><img src="'+a+'" alt=""></strong></p><h2 id="_2-确保私钥权限正确" tabindex="-1">2.确保私钥权限正确 <a class="header-anchor" href="#_2-确保私钥权限正确" aria-label="Permalink to &quot;2.确保私钥权限正确&quot;">​</a></h2><p>2.1 SSH 需要私钥文件具有特定的权限，确保私钥的权限为 <strong>600</strong>，即只有文件的拥有者可以读取和写入。</p><p>在 <strong>Mac 终端</strong> 上运行以下命令：</p><p>#chmod 600 ~/.ssh/id_ed25519</p><h2 id="_3-使用私钥登录到远程服务器" tabindex="-1">3. 使用私钥登录到远程服务器 <a class="header-anchor" href="#_3-使用私钥登录到远程服务器" aria-label="Permalink to &quot;3. 使用私钥登录到远程服务器&quot;">​</a></h2><p>3.1 使用 <code>ssh</code> 命令连接</p><p>现在你已经将 <strong>私钥</strong> 下载到 <strong>Mac</strong> 本地，并设置了正确的权限，可以使用 <strong>SSH</strong> 连接到远程服务器。</p><p>运行以下命令：</p><p>#ssh -i ~/.ssh/id_ed25519 <a href="mailto:root@192.168.1.100" target="_blank" rel="noreferrer">root@192.168.1.100</a></p><ul><li><strong><code>-i ~/.ssh/id_ed25519</code>：指定私钥文件。</strong></li><li><strong><code>root@192.168.1.100</code>：远程服务器的用户名和 IP 地址。</strong></li><li><strong>如果需要指定远程服务器的 SSH 端口，后面加 <code>-p 56251</code>。</strong></li></ul><p><strong>示例：</strong></p><p><img src="'+n+'" alt=""></p><p>如果私钥没有设置 <strong>密码短语</strong>（passphrase），SSH 会直接登录。如果设置了密码短语，系统会提示你输入 <strong>密码短语</strong>。</p><h2 id="二、finalshell工具登录方式" tabindex="-1">二、FinalShell工具登录方式 <a class="header-anchor" href="#二、finalshell工具登录方式" aria-label="Permalink to &quot;二、FinalShell工具登录方式&quot;">​</a></h2><ol><li>选择“连接管理” - “SSH连接”</li></ol><p><img src="'+i+'" alt=""></p><ol start="2"><li>名称 - 主机（IP）- 端口 - 认证方式（公钥）- 用户名 - 私钥（浏览）</li></ol><p><img src="'+l+'" alt=""></p><p>3.导入私钥：导入下载到客户端的私钥即可。</p><p><img src="'+p+'" alt=""></p><h2 id="三、windows系统" tabindex="-1">三、windows系统 <a class="header-anchor" href="#三、windows系统" aria-label="Permalink to &quot;三、windows系统&quot;">​</a></h2><h2 id="_1-将私钥下载到-windows-系统" tabindex="-1">1. 将私钥下载到 Windows 系统 <a class="header-anchor" href="#_1-将私钥下载到-windows-系统" aria-label="Permalink to &quot;1. 将私钥下载到 Windows 系统&quot;">​</a></h2><p>使用 SCP 或 FileZilla 下载私钥：</p><ul><li>如果你有 SSH 访问权限，可以使用 SCP 或 FileZilla 工具将私钥从远程服务器下载到 Windows。</li><li>例如，使用 <code>FileZilla</code> 工具下载密钥到本地：</li></ul><p><img src="'+d+'" alt=""></p><h2 id="四、putty连接方式" tabindex="-1">四、Putty连接方式 <a class="header-anchor" href="#四、putty连接方式" aria-label="Permalink to &quot;四、Putty连接方式&quot;">​</a></h2><h2 id="_1-下载并安装-putty-和-puttygen" tabindex="-1">1.下载并安装 PuTTY 和 PuTTYgen： <a class="header-anchor" href="#_1-下载并安装-putty-和-puttygen" aria-label="Permalink to &quot;1.下载并安装 PuTTY 和 PuTTYgen：&quot;">​</a></h2><p>1.1 打开PuTTYGen,载入刚下载的id_rsa私钥文件并保存</p><p>1.2 最后点击 S<strong>ave private key</strong>，生成私钥文件。</p><p><img src="'+g+'" alt=""></p><h2 id="_2-配置会话" tabindex="-1">2.配置会话： <a class="header-anchor" href="#_2-配置会话" aria-label="Permalink to &quot;2.配置会话：&quot;">​</a></h2><p>打开 PuTTY</p><p>2.1 在 <strong>Host Name (or IP address)</strong> 中输入服务器的 IP 地址。</p><p>2.2 在 <strong>Port</strong> 中输入 SSH 端口（如 <code>56251</code>）。</p><p>2.3 在 <strong>Connection type</strong> 中选择 <strong>SSH</strong>。</p><p><img src="'+c+'" alt=""></p><h2 id="_3-加载私钥" tabindex="-1">3. 加载私钥： <a class="header-anchor" href="#_3-加载私钥" aria-label="Permalink to &quot;3. 加载私钥：&quot;">​</a></h2><p>3.1 在左侧菜单中，依次展开 <strong>Connection &gt; SSH &gt; Auth</strong>。</p><p>3.2 在 <strong>Private key file for authentication</strong> 中，点击 <strong>Browse</strong>，选择你保存的 <code>.ppk</code> 文件（如 <code>id_ed25519.ppk</code>）。</p><p><img src="'+h+'" alt=""></p><h2 id="_4-连接服务器" tabindex="-1">4. 连接服务器： <a class="header-anchor" href="#_4-连接服务器" aria-label="Permalink to &quot;4. 连接服务器：&quot;">​</a></h2><p>4.1 点击 <strong>Open</strong>，启动连接。</p><p>4.2 输入用户名（如 <code>root</code>），然后按回车。</p><p>4.3 如果一切正常，你应该会成功登录到服务器。</p><p><img src="'+_+'" alt=""></p><h2 id="五、xshell连接方式" tabindex="-1">五、xshell连接方式 <a class="header-anchor" href="#五、xshell连接方式" aria-label="Permalink to &quot;五、xshell连接方式&quot;">​</a></h2><h2 id="打开-xshell" tabindex="-1">打开 Xshell： <a class="header-anchor" href="#打开-xshell" aria-label="Permalink to &quot;打开 Xshell：&quot;">​</a></h2><ol><li><strong>创建新会话</strong>：</li></ol><p>点击菜单栏的 <strong>文件 &gt; 新建</strong>，打开新建会话窗口。</p><ol start="2"><li><strong>配置连接信息</strong>：</li></ol><p>在 <strong>连接</strong> 选项卡中：</p><ul><li><strong>名称</strong>：输入会话名称。</li><li><strong>协议</strong>：选择 <strong>SSH</strong>。</li><li><strong>主机</strong>：输入服务器的 IP 地址（如 <code>107.149.212.85</code>）。</li><li><strong>端口号</strong>：输入 SSH 端口（如 <code>56251</code>）。</li></ul><p><img src="'+m+'" alt=""></p><ol start="3"><li><strong>配置身份验证</strong></li></ol><ul><li><strong>用户密钥</strong>：点击 <strong>浏览</strong>，选择你下载到本地的私钥文件（如 <code>id_ed25519</code>）。</li><li>如果私钥有密码，在 <strong>密码</strong> 中输入私钥的密码。</li></ul><p><img src="'+u+'" alt=""></p>',78)])])}const T=t(P,[["render",k]]);export{x as __pageData,T as default};
